        ELSE
          g_Alarm.alarmArray[291] := 0;
        END_IF; 
      END_IF;
      IF g_nFrontSusutainCount >= 4 THEN
        IF AntiRejection2.NCTOPLC.AxisState = 1 THEN
          g_NcAlarm.alarmArray[292] := 18015;
        ELSE
          g_Alarm.alarmArray[292] := 0;
        END_IF; 
